const view = ["screen", "window", "period", "markers", "infrastructure"];
// the fields whose value differs from the one the panel started with, or applied last
const changed = ({ elements, initial }) => elements.filter((e) => e.value !== initial[e.id]);
// on Apply, the changed levers go to the twin; the view changes once the twin has them (applied.js)
const levers = changed(context.panel).filter((e) => !view.includes(e.id));
return Object.fromEntries(levers.map((e) => [e.id, e.value]));

update.code:
const week = {"from": "2022-10-06T22:00:00.000Z", "to": "2022-10-13T22:00:00.000Z"};
// the fields whose value differs from the one the panel started with, or applied last
const changed = ({ elements, initial }) => elements.filter((e) => e.value !== initial[e.id]);
// the time a window shows: Week, the SURF week; Day or 6 h, the twin's last ones, within the week
const range = (window, twin) => {
  const hours = { day: 24, hours: 6 }[window];
  if (!hours) return week;
  const from = Math.max(new Date(twin).getTime() - hours * 3600000, new Date(week.from).getTime());
  return { from, to: from + hours * 3600000 };
};
// the twin has the levers: the form's values are the new baseline (Apply off again), and the view changes;
// refused: the API's reason
const { response, initial } = context.panel;
if (response && response.ok) {
  const sent = Object.fromEntries(changed(context.panel).map((e) => [e.id, e.value]));
  context.panel.setInitial({ ...initial, ...sent });
  const address = context.grafana.locationService;
  const view = {};
  if (sent.period) view['var-period'] = sent.period;
  if (sent.markers) view['var-markers'] = sent.markers;
  if (sent.window) {
    Object.assign(view, { 'var-window': sent.window }, range(sent.window, initial.twin_time));
  }
  if (sent.screen) {
    // not ${markers}: Grafana would put its own variable there
    const { from = week.from, to = week.to, 'var-markers': shown = 'on' } = { ...address.getSearchObject(), ...view };
    address.push(`/d/${sent.screen}?from=${from}&to=${to}&var-markers=${shown}`);
  } else {
    address.partial(view);
  }
  context.grafana.notifySuccess(['OpenDT', 'Applied']);
} else if (response) {
  response.json().then(({ detail }) => {
    const reason = typeof detail === 'string' ? detail : detail.map((d) => d.msg).join('; ');
    context.grafana.notifyError(['OpenDT', reason]);
  });
}

resetAction.code:
// Grafana's kiosk mode (no menus, no bars; Esc leaves it) in the browser's full screen, like a game
const on = !document.fullscreenElement;
on ? document.documentElement.requestFullscreen() : document.exitFullscreen();
context.grafana.locationService.partial({ kiosk: on || null });

